<?php declare(strict_types=1);require __DIR__.'/inc/db.php';require __DIR__.'/inc/page.php';require_customer();$q=$pdo->prepare('SELECT * FROM order_headers WHERE user_id=? ORDER BY created_at DESC');$q->execute([user_id()]);$orders=$q->fetchAll();page_start('My orders');?><main class="container py-4"><div class="d-flex justify-content-between align-items-end mb-4"><div><div class="eyebrow">Customer account</div><h1 class="h3 mb-0">My orders</h1></div><a class="btn btn-purple" href="view-all.php">Order another cake</a></div><?php if(!$orders):?><div class="app-card p-5 text-center"><h2 class="h5">No linked orders yet</h2><p class="help-text">Orders placed after signing in will appear here.</p><a href="legacy_claim.php">Claim a previous guest order</a></div><?php endif;?><div class="row g-3"><?php foreach($orders as $o):?><div class="col-md-6"><article class="app-card p-4 h-100"><div class="d-flex justify-content-between gap-3"><div><div class="eyebrow"><?=e($o['order_type']==='ai'?'AI cake':'Cake order')?></div><h2 class="h5 mb-1"><?=e($o['order_number'])?></h2></div><span class="status-pill align-self-start"><?=e($o['status'])?></span></div><dl class="row small mt-3 mb-3"><dt class="col-5">Pickup</dt><dd class="col-7"><?=e($o['pickup_date'])?> <?=e(substr((string)$o['pickup_time'],0,5))?></dd><dt class="col-5">Total</dt><dd class="col-7">₱<?=number_format((float)$o['total'],2)?></dd><dt class="col-5">Payment</dt><dd class="col-7"><?=e(ucfirst($o['payment_status']))?></dd></dl><a class="btn btn-outline-primary btn-sm" href="order_details.php?id=<?=(int)$o['id']?>">Track and view details</a></article></div><?php endforeach;?></div></main><?php page_end();
